g=[[1]*18 for _ in range(18)]
upper={4:[4,5,9,10],5:list(range(4,11)),6:[9],7:[7,9]}
for r,cs in upper.items():
    for c in cs:g[r-4][c]=7
lower={9:list(range(6,11)),10:list(range(7,11)),11:[7,10,11],12:[10,11],13:[10]}
for r,cs in lower.items():
    for c in cs:g[r+4][c]=7
# marker line row 8 through max col 11
for c in range(12):
    if g[8][c]!=7:g[8][c]=2
print('\n'.join(' '.join(map(str,row)) for row in g))

src={(4,4),(4,5),(4,9),(4,10),(5,4),(5,5),(5,6),(5,7),(5,8),(5,9),(5,10),(6,9),(7,7),(7,9),(8,7),(8,9),(9,6),(9,7),(9,8),(9,9),(9,10),(10,7),(10,8),(10,9),(10,10),(11,7),(11,10),(11,11),(12,10),(12,11),(13,10)}
# separate into quadrants; translate each bbox to its relevant corner
out=[[1]*18 for _ in range(18)]
beams=set()
# horizontal marker row 8 from c0..9
for c in range(10): beams.add((8,c))
# vertical marker col8 from r5..17
for r in range(5,18): beams.add((r,8))
# color beams 2 initially
for r,c in beams: out[r][c]=2
# preserve original 7 on beams
for r,c in src:
    if (r,c) in beams: out[r][c]=7
# quadrants and shifts to corners
for q in [(lambda r,c:r<8 and c<8, -4,-4),
          (lambda r,c:r<8 and c>8, -4, 7),
          (lambda r,c:r>8 and c<8, 4,-6),
          (lambda r,c:r>8 and c>8, 4, 6)]:
    pred,dr,dc=q
    for r,c in src:
        if pred(r,c):
            out[r+dr][c+dc]=7
print('\n'.join(' '.join(map(str,row)) for row in out))

# discover 4-neighbor components of non-beam 7s
movable=src-{(r,c) for r,c in src if r==8 or c==8}
comps=[]
while movable:
    stack=[movable.pop()]; comp=set(stack)
    while stack:
        r,c=stack.pop()
        for p in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
            if p in movable: movable.remove(p);comp.add(p);stack.append(p)
    comps.append(comp)
[(len(c), min(r for r,c in c),max(r for r,c in c),min(c for r,c in c),max(c for r,c in c),sorted(c)) for c in comps]
